// ==========================================================
// 1. INPUT RETRIEVAL
// ==========================================================
const caseItem = $('Limit').first().json;

let messageItems = [];
try { 
  messageItems = $('Get Messages').all(); 
} catch (e) {
  // Messages node not executed or empty
}

let fileItems = [];
try { 
  fileItems = $('Get Files').all(); 
} catch (e) {
  // File List node not executed or empty
}

// ==========================================================
// 2. STATE DETECTION (The "Smart" Logic)
// ==========================================================
let contractFileId = null;
let userFiles = [];
const hasMessages = messageItems.length > 0;

// Separate the Contract from User Evidence
fileItems.forEach(f => {
  const d = f.json;
  const name = (d["Original Name"] || "").toLowerCase();
  const isContract = name.includes("contract") || d.Message === "Contract";

  if (isContract) {
    contractFileId = d.ID;
  } else {
    userFiles.push(d);
  }
});

const hasContractPdf = contractFileId !== null;
const hasUserFiles = userFiles.length > 0;

// ==========================================================
// 3. DYNAMIC INSTRUCTION GENERATOR
// ==========================================================
let caseSpecificInstructions = [];

// A. Contract Instructions
if (hasContractPdf) {
  caseSpecificInstructions.push(
    `Download and read the Contract PDF (ID: ${contractFileId}) — this is your primary legal authority.`
  );
} else {
  caseSpecificInstructions.push(
    `No Contract PDF available. The Contract Text is your source of truth.`
  );
}

// B. Evidence Instructions
if (hasUserFiles) {
  caseSpecificInstructions.push(
    `Cross-reference the ${userFiles.length} evidence file${userFiles.length > 1 ? 's' : ''} against the messages and contract terms when needed.`
  );
} else {
  caseSpecificInstructions.push(
    `No evidence files submitted. Evaluate based on contract and messages only.`
  );
}

// C. Communication Instructions
if (!hasMessages) {
  caseSpecificInstructions.push(
    `No messages exchanged. Rely on contractual obligations and files.`
  );
}

// ==========================================================
// 4. DATA FORMATTING (Wei, Messages, Table)
// ==========================================================
const escrowFund = BigInt(caseItem["Escrow Fund"] || 0); 
const refundToBuyer = BigInt(caseItem["Refund to Buyer"] || 0); 
const paymentToSeller = BigInt(caseItem["Payment to Seller"] || 0); 
const rawAvailable = escrowFund - refundToBuyer - paymentToSeller; 
const escrowBalance = rawAvailable > 0n ? rawAvailable : 0n; 

// // Format message log
// const messageLog = hasMessages 
//   ? messageItems.map(m => {
//       const sender = m.json.Sender || "Unknown";
//       const content = m.json.Content || "";
//       return `**[${sender}]**: ${content}`;
//     }).join('\n\n')
//   : "_No messages submitted._";


// Format Message Log with Time and Source
const messageLog = hasMessages 
  ? messageItems.map(m => {
      const sender = m.json.Sender || "Unknown";
      const content = m.json.Content || "";
      const msgTime = m.json.Time ? new Date(m.json.Time).toISOString().replace('T', ' ').substring(0, 16) : "Unknown Time";

      return `**${msgTime} UTC [${sender}]**: ${content}`;
    }).join('\n\n')
  : "_No messages submitted._";



// Format file table
const fileTable = hasUserFiles
  ? userFiles.map(d => {
      const submitter = d.Submitter || "Unknown";
      const filename = d["Original Name"] || "Unnamed File";
      const id = d.ID || "N/A";
      return `| ${submitter} | ${filename} | ${id} |`;
    }).join('\n')
  : "_No user evidence files submitted._";

// ==========================================================
// 5. FINAL PROMPT ASSEMBLY
// ==========================================================

const signed_time = caseItem["Time"] ? new Date(caseItem["Time"]).toISOString().replace('T', ' ').substring(0, 16) : 'No Signing Time'; 
const time_now = new Date().toISOString().replace('T', ' ').substring(0, 16);

const userPrompt = `

# Case #${caseItem["Case ID"]}  

**Current Time:** ${time_now} UTC  
**Contract Signed:** ${signed_time} UTC   

## Parties: 
- **Buyer:** ${caseItem.Buyer} (${caseItem["Buyer Email"]})
- **Seller:** ${caseItem.Seller} (${caseItem["Seller Email"]})

## Financials: 
- **Total Escrow Fund:** ${escrowFund.toString()} Wei
- **Refunded to Buyer:** ${refundToBuyer.toString()} Wei
- **Paid to Seller:** ${paymentToSeller.toString()} Wei
- **Escrow Balance:** ${escrowBalance.toString()} Wei

## Evidence Files: 
| Source | Filename | File ID |
|--------|----------|---------|
${hasContractPdf ? `| SYSTEM | **Contract.pdf** | ${contractFileId} |\n` : ""}${fileTable}

## Messages:
${messageLog}

## Contract Text:
\`\`\`
${caseItem["Contract Text"] || "No contract text provided."}
\`\`\`

## Investigation Instructions:
${caseSpecificInstructions.map(i => `• ${i}`).join('\n\n')}`;

return { 
  user_prompt: userPrompt 
};

