// ==========================================================
// MAGISTRATE OUTPUT VALIDATION (CODE NODE VERSION)
// This adds validation_status field to the output
// Follow with a Switch node to route based on status
// ==========================================================

const data = $input.first().json.output;
const errors = [];
const warnings = [];

// ==========================================================
// 1. REQUIRED FIELD VALIDATION
// ==========================================================
const requiredFields = [
  'caseId', 'escrow_balance', 'summary', 'facts',
  'contradictions', 'unsubstantiated_claims', 'reasoning',
  'recommended_buyer_payout', 'recommended_seller_payout'
];


requiredFields.forEach(field => {
  if (data[field] === undefined || data[field] === null || data[field] === '') {
    errors.push(`Missing required field: ${field}`);
  }
});

// ==========================================================
// 2. WEI FORMAT VALIDATION
// ==========================================================
const weiPattern = /^(0|[1-9][0-9]*)$/;

if (!weiPattern.test(data.escrow_balance)) {
  errors.push(`Invalid escrow_balance format: ${data.escrow_balance}`);
}

if (!weiPattern.test(data.recommended_buyer_payout)) {
  errors.push(`Invalid recommended_buyer_payout format: ${data.recommended_buyer_payout}`);
}

if (!weiPattern.test(data.recommended_seller_payout)) {
  errors.push(`Invalid recommended_seller_payout format: ${data.recommended_seller_payout}`);
}

// ==========================================================
// 3. MATH VALIDATION
// ==========================================================
try {
  const escrow = BigInt(data.escrow_balance);
  const buyerPayout = BigInt(data.recommended_buyer_payout);
  const sellerPayout = BigInt(data.recommended_seller_payout);

  if (buyerPayout < 0n) {
    errors.push(`Negative buyer payout: ${buyerPayout}`);
  }

  if (sellerPayout < 0n) {
    errors.push(`Negative seller payout: ${sellerPayout}`);
  }

  const sum = buyerPayout + sellerPayout;
  if (sum !== escrow) {
    errors.push(`Math error: ${buyerPayout} + ${sellerPayout} = ${sum}, but escrow is ${escrow}`);
  }

  // if (escrow_balance !== escrow) {
  //   errors.push(`Data error: escrow balance is ${buyerPayout}, but it uses ${escrow}`);
  // }

  if (buyerPayout > escrow) {
    errors.push(`Buyer payout exceeds escrow`);
  }

  if (sellerPayout > escrow) {
    errors.push(`Seller payout exceeds escrow`);
  }

} catch (e) {
  errors.push(`BigInt conversion error: ${e.message}`);
}

// ==========================================================
// 3.5. MINIMUM CONTENT LENGTH VALIDATION (ERRORS)
// ==========================================================
if (!data.summary || data.summary.trim().length < 50) {
  errors.push(`Summary is critically short - minimum 50 characters required`);
}

if (!data.reasoning || data.reasoning.trim().length < 50) {
  errors.push(`Reasoning is critically short - minimum 50 characters required`);
}

// ==========================================================
// 4. ARRAY VALIDATION
// ==========================================================
if (!Array.isArray(data.facts)) {
  errors.push(`facts must be an array`);
}

if (!Array.isArray(data.contradictions)) {
  errors.push(`contradictions must be an array`);
}

if (!Array.isArray(data.unsubstantiated_claims)) {
  errors.push(`unsubstantiated_claims must be an array`);
}

// ==========================================================
// 5. CONTENT QUALITY CHECKS (Warnings)
// ==========================================================
if (data.facts && data.facts.length === 0) {
  warnings.push('No verified facts documented');
} 

// Summary should be comprehensive (200-800 chars ideal)
if (data.summary && data.summary.length < 200) {
  warnings.push('Summary is quite brief (< 200 chars) - consider adding more context');
}

if (data.summary && data.summary.length > 2000) {
  warnings.push('Summary is very long (> 1000 chars) - consider condensing');
}

// Reasoning should be thorough (300-1500 chars ideal)
if (data.reasoning && data.reasoning.length < 200) {
  warnings.push('Reasoning is brief (< 300 chars) - may lack sufficient detail for audit trail');
}

if (data.reasoning && data.reasoning.length > 2000) {
  warnings.push('Reasoning is very long (> 2500 chars) - may contain unnecessary verbosity');
}

// ==========================================================
// 6. GENERATE JUDGE PROMPT (MARKDOWN)
// ==========================================================
const caseInfo = $('Merge5').first().json; 
const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 16);
const signed_time = new Date(caseInfo.Time).toISOString().replace('T', ' ').substring(0, 16);

const magistrateReport = `
# CASE SUMMARY AND RECOMMENDATIONS

**Case ID:** ${data.caseId} 

**Current Time:** ${timestamp} UTC  
**Contract Signed:** ${signed_time} UTC   

## Parties: 
- **Buyer:** ${caseInfo.Buyer} 
- **Seller:** ${caseInfo.Seller} 


## FINANCIALS (WEI)
- **Escrow Balance:** ${data.escrow_balance}  
- **Recommended Payout to Buyer:** ${data.recommended_buyer_payout}  
- **Recommended Payout to Seller:** ${data.recommended_seller_payout}  


## MAGISTRATE REPORT  

- **Summary:** ${data.summary}  

- **Facts:** ${(data.facts || []).join(' | ')}  

- **Contradictions:** ${(data.contradictions || []).join(' | ')}  

- **Unsubstantiated claims:** ${(data.unsubstantiated_claims || []).join(' | ')}  

- **Reasoning:** ${data.reasoning}  


## CONTRACT TEXT  
\`\`\`  
${caseInfo["Contract Text"]}  
\`\`\` 

`;

// ==========================================================
// 7. RETURN WITH PROMPT AND VALIDATION STATUS
// ==========================================================
return [{
  json: {
    magistrate_report: magistrateReport,
    validation_status: errors.length > 0 ? 'ERROR' : (warnings.length > 0 ? 'WARNING' : 'SUCCESS'),
    validation_errors: errors,
    validation_warnings: warnings
  }
}];

