parameters.jsCode:
// 1. Setup Data Sources with safe fallbacks
const judgeData = $input.first().json.output || {};
const magistrateData = $('Magistrate Judge').first().json.output || {};
const errors = [];
const warnings = [];

// 2. Required Field Validation
const requiredFields = [
  'caseId', 'decision', 'escrow_balance',
  'seller_award', 'buyer_award', 
  'rationale', 'confidence'
];

requiredFields.forEach(field => {
  if (!judgeData[field] && judgeData[field] !== 0) {
    errors.push(`Missing required field: ${field}`);
  }
});

// 3. Case & Escrow Consistency
if (String(judgeData.caseId) !== String(magistrateData.caseId)) {
  errors.push(`Case ID mismatch: Judge (${judgeData.caseId}) vs Magistrate (${magistrateData.caseId})`);
}

if (String(judgeData.escrow_balance) !== String(magistrateData.escrow_balance)) {
  errors.push(`Escrow mismatch: Judge (${judgeData.escrow_balance}) vs Magistrate (${magistrateData.escrow_balance})`);
}

// 4. Content Length & Quality
const decisionLen = (judgeData.decision || '').length;
if (decisionLen < 10) {
  errors.push("Determination text too short.");
} else if (decisionLen < 50) {
  warnings.push(`Determination is short: ${decisionLen} characters.`);
} else if (decisionLen > 1000) {
  warnings.push(`Determination is long: ${decisionLen} characters.`);
}

const rationaleLen = (judgeData.rationale || '').length;
if (rationaleLen < 100) {
  errors.push("Rationale lacks sufficient detail.");
} else if (rationaleLen < 200) {
  warnings.push(`Rationale is short: ${rationaleLen} characters.`);
} else if (rationaleLen > 2000) {
  warnings.push(`Rationale is very long: ${rationaleLen} characters.`);
}

// 5. Format & Math Validation (BigInt for Wei)
const weiPattern = /^(0|[1-9][0-9]*)$/;
['escrow_balance', 'seller_award', 'buyer_award'].forEach(key => {
  if (!weiPattern.test(String(judgeData[key] || ''))) {
    errors.push(`Invalid Wei format for ${key}: ${judgeData[key]}`);
  }
});

try {
  const escrow = BigInt(judgeData.escrow_balance || 0);
  const sellerAward = BigInt(judgeData.seller_award || 0);
  const buyerAward = BigInt(judgeData.buyer_award || 0);
  const totalAwarded = sellerAward + buyerAward;

  if (sellerAward < 0n || buyerAward < 0n) errors.push("Negative award values detected.");
  if (totalAwarded !== escrow) {
    errors.push(`Math Error: Awards (${totalAwarded}) do not match Escrow (${escrow})`);
  }
} catch (e) {
  errors.push(`Calculation Error: ${e.message}`);
}

// 6. Generate Final Markdown Report
const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 16);
const confidencePct = judgeData.confidence ? (judgeData.confidence * 100).toFixed(0) : "0";

const finalDeterminationHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <style>
        body { font-family: 'Times New Roman', serif; line-height: 1.6; color: #333; max-width: 800px; margin: 40px auto; padding: 50px; border: 1px solid #ccc; box-shadow: 0 0 10px rgba(0,0,0,0.05); }
        .header { text-align: center; border-bottom: 2px solid #2c3e50; margin-bottom: 30px; padding-bottom: 10px; }
        h1 { color: #2c3e50; font-size: 24px; text-transform: uppercase; }
        h2 { color: #2c3e50; font-size: 18px; border-bottom: 1px solid #eee; padding-bottom: 5px; margin-top: 30px; }
        .decision { background: #f8f9fa; padding: 15px; border-left: 4px solid #2c3e50; font-weight: bold; margin: 15px 0; }
        ul { list-style-type: none; padding: 0; }
        li { margin-bottom: 8px; font-size: 15px; }
        .footer { margin-top: 40px; font-size: 13px; color: #7f8c8d; border-top: 1px solid #eee; padding-top: 15px; text-align: center; }
        .print-btn { display: block; margin: 30px auto 0; padding: 10px 20px; background: #2c3e50; color: #fff; border: none; border-radius: 4px; cursor: pointer; }
        @media print { .print-btn { display: none; } body { border: none; box-shadow: none; margin: 0; padding: 20px; } }
    </style>
</head>
<body>
    <div class="header">
        <h1>FINAL DETERMINATION - CASE #${judgeData.caseId || 'N/A'}</h1>
        <p><strong>Date Issued:</strong> ${timestamp} UTC</p>
    </div>

    <h2>⚖️ DECISION</h2>
    <div class="decision">
        ${judgeData.decision || 'No decision provided.'}
    </div>

    <h2>💰 FINANCIAL AWARDS (WEI)</h2>
    <ul>
        <li><strong>Total Escrow Balance:</strong> ${judgeData.escrow_balance || '0'}</li>
        <li><strong>Awarded to Buyer:</strong> ${judgeData.buyer_award || '0'}</li>
        <li><strong>Awarded to Seller:</strong> ${judgeData.seller_award || '0'}</li>
    </ul>

    <h2>📝 RATIONALE</h2>
    <p>${judgeData.rationale || 'No rationale provided.'}</p>

    <div class="footer">
        <p><em>AI Confidence Score: ${confidencePct}%</em></p>
    </div>

    <button class="print-btn" onclick="window.print()">Print to PDF</button>
</body>
</html>
`;

// 7. Final Output
return [{
  json: {
    ...judgeData,
    finalDeterminationHtml,
    validationStatus: errors.length > 0 ? 'ERROR' : (warnings.length > 0 ? 'WARNING' : 'SUCCESS'),
    validationErrors: errors,
    validationWarnings: warnings
  }
}];

