const data = $input.first().json;
const report = data.magistrate_report || '';

// 1. Extract values directly from the markdown string
const caseIdMatch = report.match(/Case ID:\*\*\s*(\d+)/);
const caseId = caseIdMatch ? caseIdMatch[1] : 'UNKNOWN';

const escrowMatch = report.match(/Escrow Balance:\*\*\s*(-?\d+)/);
const buyerMatch = report.match(/Recommended Payout to Buyer:\*\*\s*(-?\d+)/);
const sellerMatch = report.match(/Recommended Payout to Seller:\*\*\s*(-?\d+)/);

const escrowWei = escrowMatch ? parseFloat(escrowMatch[1]) : 0;
const buyerWei = buyerMatch ? parseFloat(buyerMatch[1]) : 0;
const sellerWei = sellerMatch ? parseFloat(sellerMatch[1]) : 0;

// 2. Financial Conversion (Wei to ETH)
const escrowEth = (escrowWei / 1e18).toFixed(4);
const bEth = (buyerWei / 1e18).toFixed(4);
const sEth = (sellerWei / 1e18).toFixed(4);

// 3. Format Lists
const errItems = (data.validation_errors || []).map(e => `<li>${e}</li>`).join('');
const warnItems = (data.validation_warnings || []).map(w => `<li>${w}</li>`).join('');

// 4. Email Logic
const isError = data.validation_status === 'ERROR' || (data.validation_errors || []).length > 0;
const color = isError ? '#e53e3e' : '#ed6c02';
const label = isError ? 'MAGISTRATE VALIDATION FAILED' : 'MAGISTRATE WARNING';

const htmlBody = `
<div style="font-family: sans-serif; border: 2px solid ${color}; max-width: 600px; border-radius: 8px; overflow: hidden;">
  <div style="background-color: ${color}; color: white; padding: 20px; text-align: center;">
    <h2 style="margin: 0;">${label}</h2>
    <p style="margin: 5px 0 0;">Case ID: #${caseId}</p>
  </div>
  <div style="padding: 20px;">
